import { Fragment, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Archive, Bold, ChevronLeft, ChevronRight, Download, FileText, FolderCog, Forward, Inbox, Italic, Link, List, ListOrdered, LoaderCircle, Mail, MailOpen, Menu, Moon, Paperclip, PenLine, Plus, Redo2, Reply, ReplyAll, Save, Search, Send, Settings, ShieldOff, Bell, SlidersHorizontal, Star, Sun, Tags, Trash2, Underline, Undo2, Upload, Users, X } from 'lucide-react';
import { api } from './api';
import { BlockedSenders } from './BlockedSenders';
import { NotificationSettings } from './NotificationSettings';
import { Identities } from './Identities';
import { AttachmentPreview } from './AttachmentPreview';
import { RecipientInput } from './RecipientInput';
import { groupSelections, parseSelectionKey, selectionFromRow } from './mailSelection';
import type { Attachment, Contact, Draft, Folder, Identity, Label, MailRow, MailTemplate, Message, Preferences, SearchFilters, Session } from './types';

type LoadedMessage={message:Message;attachments:Attachment[];safeHtml:string;hasRemoteImages:boolean;remoteUrl:string};
const folderNames:Record<string,string>={inbox:'Recibidos',sent:'Enviados',drafts:'Borradores',junk:'Spam',trash:'Papelera',archive:'Archivo',flagged:'Destacados'};
function displayFolderName(name:string):string{return name.replace(/^INBOX[.]/i,'')||name}
const requestedAccount=new URLSearchParams(location.search).get('account');if(requestedAccount)sessionStorage.setItem('axerok-account',requestedAccount.toLowerCase());
const emptyPreferences:Preferences={signature_html:'',receipt_default:false,display_name:'',organization:'',reply_to:'',default_bcc:'',view_density:'comfortable',inbox_view:'categories'};
const emptyDraft:Draft={id:'',to:'',cc:'',bcc:'',subject:'',body_html:'',receipt_requested:false,priority:'normal'};
const emptySearch:SearchFilters={from:'',to:'',subject:'',contains:'',exclude:'',status:'all',size_op:'',size_value:'',size_unit:'MB',since:'',before:'',has_attachment:false};

export function App(){const[session,setSession]=useState<Session|null>(null);const[error,setError]=useState('');const[theme,setTheme]=useState<'light'|'dark'>(()=>localStorage.getItem('axerok-theme')==='dark'?'dark':'light');useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('axerok-theme',theme)},[theme]);useEffect(()=>{let active=true;const refresh=()=>{setError('');api.session().then(value=>{if(active){if((value as Session&{account_unavailable?:boolean}).account_unavailable)sessionStorage.removeItem('axerok-account');setSession(value)}}).catch(e=>{if(active)setError(e.message)})};const expired=()=>{sessionStorage.removeItem('axerok-account');setSession(current=>current?{...current,authenticated:false,email:null}:current);api.session().then(value=>{if(active)setSession({...value,authenticated:false,email:null})}).catch(e=>{if(active)setError(e.message)})};refresh();window.addEventListener('axerok:session-expired',expired);return()=>{active=false;window.removeEventListener('axerok:session-expired',expired)}},[]);if(!session)return <Splash error={error}/>;if(!session.authenticated)return <Login session={session} onLogin={setSession}/>;return <Mailbox session={session} onLogout={setSession} theme={theme} onTheme={()=>setTheme(theme==='light'?'dark':'light')}/>}
function Splash({error}:{error:string}){return <main className="splash"><Brand/><LoaderCircle className="spin"/><p>{error||'Preparando tu correo…'}</p></main>}
function Login({session,onLogin}:{session:Session;onLogin:(s:Session)=>void}){const[busy,setBusy]=useState(false);const[error,setError]=useState('');async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');const data=new FormData(event.currentTarget);try{onLogin(await api.login(String(data.get('email')),String(data.get('password')),session.csrf))}catch(e){setError((e as Error).message);setBusy(false)}}return <main className="login"><section><Brand/><h1>Tu correo, más simple</h1><p>Ingresá con la misma cuenta que usás en Roundcube.</p>{error&&<div className="error">{error}</div>}<form onSubmit={submit}><label>Correo electrónico<input name="email" type="email" required autoComplete="username"/></label><label>Contraseña<input name="password" type="password" required autoComplete="current-password"/></label><button disabled={busy}>{busy?'Ingresando…':'Ingresar'}</button></form></section></main>}

function AccountMenu({session}:{session:Session}){const[open,setOpen]=useState(false);const[adding,setAdding]=useState(false);const[busy,setBusy]=useState(false);const[error,setError]=useState('');async function choose(email:string){setBusy(true);try{sessionStorage.setItem('axerok-account',email);await api.switchAccount(email,session.csrf);location.href=location.pathname}catch(e){setError((e as Error).message);setBusy(false)}}async function add(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');const form=new FormData(event.currentTarget);try{const email=String(form.get('email')).toLowerCase();sessionStorage.setItem('axerok-account',email);await api.login(email,String(form.get('password')),session.csrf);location.href=location.pathname}catch(e){setError((e as Error).message);setBusy(false)}}async function remove(email:string){if(!confirm(`¿Cerrar la cuenta ${email} en este navegador?`))return;setBusy(true);try{const next=await api.removeAccount(email,session.csrf);if(sessionStorage.getItem('axerok-account')===email)sessionStorage.setItem('axerok-account',next.email||'');location.href=location.pathname}catch(e){setError((e as Error).message);setBusy(false)}}function newTab(email:string){window.open(`${location.pathname}?account=${encodeURIComponent(email)}`,'_blank','noopener,noreferrer')}return <div className="accountMenu"><button className="user accountButton" onClick={()=>setOpen(!open)}>{session.email?.slice(0,2).toUpperCase()}</button>{open&&<section className="accountPanel"><header><b>Cuentas abiertas</b><button onClick={()=>setOpen(false)}><X/></button></header>{error&&<div className="error">{error}</div>}{session.accounts.map(email=><div className={`accountRow ${email===session.email?'active':''}`} key={email}><div className="miniAvatar">{email.slice(0,2).toUpperCase()}</div><span><b>{email}</b>{email===session.email&&<small>Activa en esta pestaña</small>}</span><button disabled={busy||email===session.email} onClick={()=>void choose(email)}>Cambiar</button><button title="Abrir en otra pestaña" onClick={()=>newTab(email)}>↗</button><button title="Cerrar cuenta" disabled={busy} onClick={()=>void remove(email)}><X/></button></div>)}{adding?<form className="addAccount" onSubmit={add}><input name="email" type="email" required placeholder="Correo electrónico"/><input name="password" type="password" required placeholder="Contraseña"/><button disabled={busy}>{busy?'Verificando…':'Agregar y abrir'}</button></form>:<button className="addAccountButton" onClick={()=>setAdding(true)}><Plus/>Añadir otra cuenta</button>}</section>}</div>}

function Mailbox({session,onLogout,theme,onTheme}:{session:Session;onLogout:(session:Session)=>void;theme:'light'|'dark';onTheme:()=>void}){
 useEffect(()=>{sessionStorage.setItem('axerok-page-size',String(session.page_size||40));if(session.email)sessionStorage.setItem('axerok-account',session.email)},[session.page_size,session.email]);
 const[total,setTotal]=useState(0);
 const[folders,setFolders]=useState<Folder[]>([]);const[labels,setLabels]=useState<Label[]>([]);const[labelFilter,setLabelFilter]=useState<Label|null>(null);const[clientEmails,setClientEmails]=useState<Set<string>>(new Set());const[folder,setFolder]=useState('INBOX');const[mailPage,setMailPage]=useState(1);const[rows,setRows]=useState<MailRow[]>([]);const[selected,setSelected]=useState<LoadedMessage|null>(null);const[selectedUids,setSelectedUids]=useState<Set<string>>(new Set());const[query,setQuery]=useState('');const[searchBody,setSearchBody]=useState(false);const[searchFilters,setSearchFilters]=useState<SearchFilters>(emptySearch);const[showAdvanced,setShowAdvanced]=useState(false);const[activeTab,setActiveTab]=useState<'principal'|'clients'|'notifications'>('principal');const[collapsed,setCollapsed]=useState(false);const[busy,setBusy]=useState(true);const[error,setError]=useState('');const[notice,setNotice]=useState('');const[compose,setCompose]=useState(false);const[composeSeed,setComposeSeed]=useState<Draft|null>(null);const[draftRevision,setDraftRevision]=useState(0);const[page,setPage]=useState<'mail'|'drafts'|'contacts'|'settings'|'folders'|'labels'|'blocked'|'notifications'|'identities'>('mail');const[preferences,setPreferences]=useState<Preferences>(emptyPreferences);
 useEffect(()=>{if(page==='mail'&&!selected)return;let active=true;let running=false;const check=async()=>{if(!active||running||document.visibilityState!=='visible'||!navigator.onLine)return;running=true;try{await api.ping();if(active)setError('')}catch(e){if(active)setError((e as Error).message)}finally{running=false}};const resume=()=>void check();const timer=window.setInterval(resume,45000);window.addEventListener('focus',resume);window.addEventListener('online',resume);document.addEventListener('visibilitychange',resume);void check();return()=>{active=false;window.clearInterval(timer);window.removeEventListener('focus',resume);window.removeEventListener('online',resume);document.removeEventListener('visibilitychange',resume)}},[page,selected]);
 useEffect(()=>{Promise.all([api.folders(),api.preferences(),api.labels(),api.contacts()]).then(([f,p,l,c])=>{setFolders(f.folders);setPreferences(p.preferences);setLabels(l.labels);setClientEmails(new Set(c.contacts.map(item=>item.email.toLowerCase())))}).catch(e=>setError(e.message))},[]);
 useEffect(()=>{const openComposer=(event:Event)=>{setComposeSeed((event as CustomEvent<Draft>).detail);setCompose(true)};window.addEventListener('axerok:compose',openComposer);return()=>window.removeEventListener('axerok:compose',openComposer)},[]);
 useEffect(()=>{if(page==='mail'||page==='settings'){api.contacts().then(c=>setClientEmails(new Set(c.contacts.map(item=>item.email.toLowerCase())))).catch(e=>setError(e.message));api.preferences().then(p=>setPreferences(p.preferences)).catch(e=>setError(e.message))}},[page]);
 const load=useCallback(async(f=folder,q=query,body=searchBody,fresh=false,filters=searchFilters,p=mailPage)=>{setBusy(true);setError('');setSelectedUids(new Set());try{const[result,blocked]=await Promise.all([api.messages(f,q,body,fresh,filters,p),api.blockedSenders()]);const denied=new Set(blocked.senders);setRows(result.messages.filter(row=>!denied.has(emailFromHeader(row.from))));setTotal(result.total);setMailPage(p)}catch(e){setError((e as Error).message)}finally{setBusy(false)}},[folder,query,searchBody,searchFilters,mailPage]);
 useEffect(()=>{if(page!=='mail'||selected)return;let active=true;let running=false;const refresh=async()=>{if(!active||running||document.visibilityState!=='visible'||!navigator.onLine)return;running=true;try{const[result,blocked]=await Promise.all([api.messages(folder,query,searchBody,true,searchFilters,mailPage),api.blockedSenders()]);if(!active)return;const denied=new Set(blocked.senders);setRows(result.messages.filter(row=>!denied.has(emailFromHeader(row.from))));setError('');setTotal(previous=>{if(previous>0&&result.total>previous){setNotice(`${result.total-previous} mensaje${result.total-previous===1?' nuevo':'s nuevos'}.`);announceNewMessages(result.total,previous)}return result.total})}catch(e){if(active)setError((e as Error).message)}finally{running=false}};const timer=window.setInterval(()=>void refresh(),30000);const resume=()=>void refresh();window.addEventListener('focus',resume);window.addEventListener('online',resume);document.addEventListener('visibilitychange',resume);return()=>{active=false;window.clearInterval(timer);window.removeEventListener('focus',resume);window.removeEventListener('online',resume);document.removeEventListener('visibilitychange',resume)}},[page,selected,folder,query,searchBody,searchFilters,mailPage]);
 useEffect(()=>{if(page==='mail'){setSelected(null);setMailPage(1);void load(folder,'',searchBody,false,searchFilters,1)}},[folder,page]);
 async function open(row:MailRow){setBusy(true);try{setSelected(await api.message(row.folder,row.uid));if(!row.seen)setRows(current=>current.map(item=>item.folder===row.folder&&item.uid===row.uid?{...item,seen:true}:item))}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 const selectedUidsForFolder=()=>Array.from(selectedUids).map(key=>key.split("\0")).filter(parts=>parts[0]===folder).map(parts=>Number(parts[1])).filter(Number.isSafeInteger);
 const selectedGroups=()=>groupSelections(Array.from(selectedUids).map(parseSelectionKey).filter((item):item is {folder:string;uid:number}=>item!==null));
 function announceNewMessages(nextTotal:number,previousTotal:number){
  if(nextTotal<=previousTotal||!('Notification' in window)||Notification.permission!=='granted')return;
  const key=`axerok-notified:${session.email}:${folder}:${query}`;const marker=`${nextTotal}`;
  if(localStorage.getItem(key)===marker)return;
  localStorage.setItem(key,marker);new Notification('AxerOK Webmail',{body:`${nextTotal-previousTotal} mensaje${nextTotal-previousTotal===1?'':'s'} nuevo${nextTotal-previousTotal===1?'':'s'}.`});
 }
 async function updateSelectedGlobal(flag:'seen'|'flagged',enabled:boolean){for(const [source,uids] of selectedGroups())await api.updateFlags(source,uids,flag,enabled,session.csrf);setSelectedUids(new Set());await load('*',query,searchBody,true,searchFilters,mailPage)}
 async function moveSelectedGlobal(destination:string){for(const [source,uids] of selectedGroups())await api.moveMessages(source,uids,destination,session.csrf);setSelectedUids(new Set());await load('*',query,searchBody,true,searchFilters,mailPage)}
 async function deleteSelectedGlobal(){for(const [source,uids] of selectedGroups())await api.deleteMessages(source,uids,session.csrf);setSelectedUids(new Set());await load('*',query,searchBody,true,searchFilters,mailPage)}
 async function updateFlags(uids:number[],flag:'seen'|'flagged',enabled:boolean){if(!uids.length)return;setError('');setRows(current=>current.map(item=>uids.includes(item.uid)?{...item,[flag]:enabled}:item));try{await api.updateFlags(folder,uids,flag,enabled,session.csrf);setSelectedUids(new Set())}catch(e){setError((e as Error).message);void load(folder,query,searchBody,true)}}
 async function moveSelected(uids:number[],destination:string,success:string){if(!uids.length||!destination)return;setBusy(true);setError('');try{await api.moveMessages(folder,uids,destination,session.csrf);setSelected(null);setSelectedUids(new Set());setNotice(success);await load(folder,query,searchBody,true)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function deleteSelected(uids:number[]){if(!uids.length)return;const permanent=folders.find(item=>item.name===folder)?.special==='trash';if(permanent&&!confirm(`¿Eliminar definitivamente ${uids.length} mensaje${uids.length===1?'':'s'}? Esta acción no se puede deshacer.`))return;setBusy(true);setError('');try{await api.deleteMessages(folder,uids,session.csrf);setSelected(null);setSelectedUids(new Set());setNotice(permanent?'Mensajes eliminados definitivamente.':'Mensajes movidos a la Papelera.');await load(folder,query,searchBody,true,searchFilters,mailPage)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function emptyCurrent(){const special=folders.find(item=>item.name===folder)?.special;if(!['junk','trash'].includes(special||''))return;const label=special==='junk'?'Spam':'Papelera';if(!confirm(`¿Eliminar definitivamente los ${total.toLocaleString('es-AR')} mensajes de ${label}? Esta acción no se puede deshacer.`))return;setBusy(true);setError('');try{const result=await api.emptyFolder(folder,session.csrf);setNotice(`${result.deleted.toLocaleString('es-AR')} mensajes eliminados definitivamente.`);setMailPage(1);await load(folder,'',false,true,emptySearch,1)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function logout(){try{await api.logout(session.csrf);onLogout(await api.session())}catch(e){setError((e as Error).message)}}
 const visibleFolders=useMemo(()=>folders.filter((item,index,self)=>self.findIndex(other=>(other.special||other.name)===(item.special||displayFolderName(item.name)))===index),[folders]);
 const spamFolder=folders.find(item=>item.special==='junk')?.name||'';
 const inboxFolder=folders.find(item=>item.special==='inbox')?.name||'INBOX';
 const archiveFolder=folders.find(item=>item.special==='archive')?.name||'';
 const currentSpecial=folders.find(item=>item.name===folder)?.special||null;
 const spamAction=spamFolder?(folder===spamFolder?{label:'No es spam',run:(uids:number[])=>moveSelected(uids,inboxFolder,'Mensaje restaurado en Recibidos.')}:{label:'Spam',run:(uids:number[])=>moveSelected(uids,spamFolder,'Mensaje movido a Spam.')}):undefined;
 return <div className={`shell ${collapsed?'collapsed':''} density-${preferences.view_density}`}><header><button className="round" title={collapsed?'Expandir menú':'Contraer menú'} onClick={()=>setCollapsed(!collapsed)}><Menu/></button><Brand/><form className="search" onSubmit={e=>{e.preventDefault();setSelected(null);setLabelFilter(null);setPage('mail');void load(folder,query,searchBody)}}><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={folder==="*"?"Buscar en todas las carpetas":"Buscar en esta carpeta"}/><label className="searchBody"><input type="checkbox" checked={searchBody} onChange={e=>setSearchBody(e.target.checked)}/><span>Buscar también en cuerpo de mensaje</span></label><button type="button" title="Búsqueda avanzada" onClick={()=>setShowAdvanced(!showAdvanced)}><SlidersHorizontal/></button>{query&&<button type="button" onClick={()=>{setQuery('');setSelected(null);setLabelFilter(null);setPage('mail');void load(folder,'',searchBody)}}><X/></button>}</form><button className="round themeToggle" onClick={onTheme} title={theme==='light'?'Usar modo oscuro':'Usar modo claro'}>{theme==='light'?<Moon/>:<Sun/>}</button><AccountMenu session={session}/></header>
 {showAdvanced&&<AdvancedSearch value={searchFilters} onChange={setSearchFilters} onClose={()=>setShowAdvanced(false)} onSearch={()=>{setShowAdvanced(false);setSelected(null);setLabelFilter(null);setPage('mail');void load(folder,query,searchBody,false,searchFilters)}}/>}
 <aside><button className="compose" onClick={()=>setCompose(true)}><PenLine/><span>Redactar</span></button><nav>{visibleFolders.map(item=><button className={(item.special==='drafts'?page==='drafts':page==='mail'&&folder===item.name)?'active':''} key={item.name} onClick={()=>{setSelected(null);setActiveTab('principal');if(item.special==='drafts'){setPage('drafts');return}setPage('mail');if(folder===item.name)void load(item.name,query,searchBody,true);else setFolder(item.name)}}>{folderIcon(item.special)}<span>{folderNames[item.special||'']||displayFolderName(item.name)}</span></button>)}</nav><div className="tools"><button className={page==='contacts'?'active':''} onClick={()=>setPage('contacts')}><Users/><span>Contactos</span></button><button className={page==='folders'?'active':''} onClick={()=>setPage('folders')}><FolderCog/><span>Administrar carpetas</span></button><button className={page==='labels'?'active':''} onClick={()=>setPage('labels')}><Tags/><span>Etiquetas</span></button><button className={page==='settings'?'active':''} onClick={()=>setPage('settings')}><Settings/><span>Configuración</span></button><button className={page==='blocked'?'active':''} onClick={()=>setPage('blocked')}><ShieldOff/><span>Remitentes bloqueados</span></button><button className={page==='notifications'?'active':''} onClick={()=>setPage('notifications')}><Bell/><span>Notificaciones</span></button><button className={page==='identities'?'active':''} onClick={()=>setPage('identities')}><Send/><span>Identidades</span></button>{session.webmail_home_url&&<a className="webmailHome" href={session.webmail_home_url}><Mail/><span>Inicio de Webmail</span></a>}</div><div className="sidebarLabels"><b>Etiquetas</b>{labels.map(label=><button type="button" key={label.id} onClick={()=>{setLabelFilter(label);setPage("mail");setSelected(null)}}><i style={{backgroundColor:label.color}}/><span>{label.name}</span></button>)}</div><small className="accountLabel">{session.email}<i>AxerOK Mail v{session.version}</i></small><button className="logout" onClick={logout}>Cerrar todas las cuentas</button></aside>
 <section className="content">{error&&<div className="error banner">{error}</div>}{notice&&<div className="success banner">{notice}</div>}{busy&&<div className="progress"/>}{page==='drafts'?<DraftList key={draftRevision} csrf={session.csrf} onOpen={draft=>{setComposeSeed(draft);setCompose(true)}}/>:page==='contacts'?<Contacts csrf={session.csrf}/>:page==='folders'?<FolderManager csrf={session.csrf} items={folders} onChange={setFolders}/>:page==='labels'?<LabelManager csrf={session.csrf} items={labels} onChange={setLabels}/>:page==='settings'?<PreferencesView csrf={session.csrf} value={preferences} onChange={setPreferences} onNotice={setNotice}/>:page==='blocked'?<BlockedSenders csrf={session.csrf} onNotice={setNotice}/>:page==='notifications'?<NotificationSettings onNotice={setNotice}/>:page==='identities'?<Identities csrf={session.csrf} onNotice={setNotice}/>:selected?<Reader data={selected} folder={folder} csrf={session.csrf} onBack={()=>setSelected(null)} onDeleted={()=>{setSelected(null);setNotice('Mensaje movido a la Papelera.');void load(folder,query,searchBody,true)}} spamAction={spamAction&&folder!=='*'?{label:spamAction.label,onClick:()=>void spamAction.run([selected.message.uid])}:undefined}/>:<MailList rows={labelFilter?rows.filter(row=>(row.keywords||[]).includes(labelFilter.keyword)):rows} total={labelFilter?rows.filter(row=>(row.keywords||[]).includes(labelFilter.keyword)).length:total} labels={labels} folders={visibleFolders} currentFolder={folder} currentSpecial={currentSpecial} archiveFolder={archiveFolder} mailPage={mailPage} clientEmails={clientEmails} inboxView={preferences.inbox_view} activeTab={activeTab} onTab={tab=>{setActiveTab(tab);setSelectedUids(new Set())}} selected={selectedUids} onOpen={open} onSelect={(row,checked)=>setSelectedUids(current=>{const next=new Set(current);const key=selectionFromRow(row);checked?next.add(key):next.delete(key);return next})} onSelectAll={(checked,rows)=>setSelectedUids(checked?new Set(rows.map(selectionFromRow)):new Set())} onFlag={(row,enabled)=>void updateFlags([row.uid],'flagged',enabled)} onBulk={(flag,enabled)=>void (folder==='*'?updateSelectedGlobal(flag,enabled):updateFlags(selectedUidsForFolder(),flag,enabled))} onDelete={()=>void (folder==='*'?deleteSelectedGlobal():deleteSelected(selectedUidsForFolder()))} onEmpty={()=>void emptyCurrent()}  onMove={destination=>void (folder==='*'?moveSelectedGlobal(destination):moveSelected(selectedUidsForFolder(),destination,'Mensajes movidos correctamente.'))} onPage={next=>void load(folder,query,searchBody,false,searchFilters,next)} spamAction={spamAction&&folder!=="*"?{label:spamAction.label,onClick:()=>void spamAction.run(selectedUidsForFolder())}:undefined} onLabel={(label,enabled)=>{const uids=selectedUidsForFolder();setRows(current=>current.map(row=>{const keywords=row.keywords||[];return uids.includes(row.uid)?{...row,keywords:enabled?[...new Set([...keywords,label.keyword])]:keywords.filter(item=>item!==label.keyword)}:row}));void api.applyLabel(folder,uids,label.id,enabled,session.csrf).then(()=>setSelectedUids(new Set())).catch(e=>{setError(e.message);void load(folder,query,searchBody,true)})}}/>}</section>
 {compose&&<Composer from={session.email||''} csrf={session.csrf} preferences={preferences} initialDraft={composeSeed} onClose={()=>{setCompose(false);setComposeSeed(null);setDraftRevision(value=>value+1)}} onSent={warning=>{setCompose(false);setComposeSeed(null);setNotice(warning?`Mensaje enviado. ${warning}`:'Mensaje enviado correctamente.');void load()}}/>}</div>
}

type SpamAction={label:string;onClick:()=>void};
function MailList({rows,total,labels,folders,currentFolder,currentSpecial,archiveFolder,mailPage,clientEmails,inboxView,activeTab,onTab,selected,onOpen,onSelect,onSelectAll,onFlag,onBulk,onDelete,onEmpty,onMove,onPage,spamAction,onLabel}:{rows:MailRow[];total:number;labels:Label[];folders:Folder[];currentFolder:string;currentSpecial:string|null;archiveFolder:string;mailPage:number;clientEmails:Set<string>;inboxView:Preferences['inbox_view'];activeTab:'principal'|'clients'|'notifications';onTab:(tab:'principal'|'clients'|'notifications')=>void;selected:Set<string>;onOpen:(row:MailRow)=>void;onSelect:(row:Pick<MailRow,"folder"|"uid">,checked:boolean)=>void;onSelectAll:(checked:boolean,rows:Array<Pick<MailRow,"folder"|"uid">>)=>void;onFlag:(row:MailRow,enabled:boolean)=>void;onBulk:(flag:'seen'|'flagged',enabled:boolean)=>void;onDelete:()=>void;onEmpty:()=>void;onMove:(destination:string)=>void;onPage:(page:number)=>void;spamAction?:SpamAction;onLabel:(label:Label,enabled:boolean)=>void}){
 const classified=rows.map(row=>({...row,isClient:clientEmails.has(emailFromHeader(row.from))}));
 const categorized=inboxView==='categories'?classified.filter(row=>activeTab==='clients'?row.isClient:activeTab==='notifications'?row.category==='notification':true):classified;
 const displayRows=[...categorized].sort((a,b)=>inboxView==='unread'?Number(a.seen)-Number(b.seen):inboxView==='starred'?Number(b.flagged)-Number(a.flagged):0);
 const all=displayRows.length>0&&displayRows.every(row=>selected.has(selectionFromRow(row)));
 function labelChange(value:string,event:React.ChangeEvent<HTMLSelectElement>){if(!value)return;const[operation,id]=value.split(':');const label=labels.find(item=>item.id===Number(id));if(label)onLabel(label,operation==='add');event.currentTarget.value=''}
 const pages=Math.max(1,Math.ceil(total/(Number(sessionStorage.getItem('axerok-page-size'))||40)));
 return <>
  <div className="listbar actionsBar">
   <label><input type="checkbox" disabled={currentFolder==="*"} checked={all} onChange={e=>onSelectAll(e.target.checked,displayRows)}/><span>Seleccionar {displayRows.length} visibles</span></label>
   {selected.size>0?<div className="bulkActions"><b>{selected.size} seleccionados</b><button onClick={()=>onBulk('seen',true)}><MailOpen/><span>Leídos</span></button><button onClick={()=>onBulk('seen',false)}><Mail/><span>No leídos</span></button><button onClick={()=>onBulk('flagged',true)}><Star/><span>Destacar</span></button><button onClick={()=>onBulk('flagged',false)}><X/><span>Quitar destacado</span></button>{archiveFolder&&archiveFolder!==currentFolder&&<button onClick={()=>onMove(archiveFolder)}><Archive/><span>Archivar</span></button>}<button className="dangerBulk" onClick={onDelete}><Trash2/><span>{currentSpecial==='trash'?'Eliminar definitivamente':'Eliminar'}</span></button>{spamAction&&<button onClick={spamAction.onClick}><Inbox/><span>{spamAction.label}</span></button>}<select defaultValue="" aria-label="Mover mensajes" onChange={e=>{if(e.target.value)onMove(e.target.value);e.currentTarget.value=''}}><option value="">Mover a…</option>{folders.filter(item=>item.name!==currentFolder&&!item.flags?.includes('\\Noselect')).map(item=><option value={item.name} key={item.name}>{folderNames[item.special||'']||displayFolderName(item.name)}</option>)}</select>{labels.length>0&&currentFolder!=='*'&&<select defaultValue="" aria-label="Aplicar etiqueta" onChange={e=>labelChange(e.target.value,e)}><option value="">Etiquetas…</option>{labels.map(label=><option key={`add-${label.id}`} value={`add:${label.id}`}>Agregar: {label.name}</option>)}{labels.map(label=><option key={`remove-${label.id}`} value={`remove:${label.id}`}>Quitar: {label.name}</option>)}</select>}</div>:(['junk','trash'].includes(currentSpecial||'')&&total>0)&&<button className="emptyFolderButton" onClick={onEmpty}>Vaciar {currentSpecial==='junk'?'Spam':'Papelera'}</button>}
   <span>{displayRows.length} visibles · {total.toLocaleString('es-AR')} total</span>
  </div>
  {inboxView==='categories'&&<div className="tabs"><button className={activeTab==='principal'?'active':''} onClick={()=>onTab('principal')}>Principal</button><button className={activeTab==='clients'?'active':''} onClick={()=>onTab('clients')} title="Remitentes que existen en Contactos (sobre los mensajes visibles)">Contactos</button><button className={activeTab==='notifications'?'active':''} onClick={()=>onTab('notifications')}>Notificaciones</button></div>}
  <div className="rows">{displayRows.map(row=>{const rowLabels=labels.filter(label=>(row.keywords||[]).includes(label.keyword));return <div key={`${row.folder}-${row.uid}`} className={`mailRow ${row.seen?'':'unread'} ${selected.has(selectionFromRow(row))?'selected':''}`} onClick={()=>onOpen(row)}><label className="rowSelect" title="Seleccionar mensaje" onClick={e=>e.stopPropagation()}><input className="rowCheck" type="checkbox" aria-label={`Seleccionar ${row.subject}`} checked={selected.has(selectionFromRow(row))} onChange={e=>onSelect(row,e.target.checked)}/></label><button className="starButton" title={row.flagged?'Quitar destacado':'Destacar'} onClick={e=>{e.stopPropagation();onFlag(row,!row.flagged)}}><Star className={row.flagged?'gold':''}/></button><span className="senderName">{row.from}</span>{currentFolder==="*"&&<small className="resultFolder">{folderNames[folders.find(item=>item.name===row.folder)?.special||""]||row.folder}</small>}<span className="subject"><span className="subjectText">{row.subject}</span>{rowLabels.map(label=><span className="labelChip" style={{borderColor:label.color,color:label.color}} key={label.id}>{label.name}</span>)} — {Math.round(row.size/1024)} KB</span><time>{shortDate(row.date)}</time></div>})}{!displayRows.length&&<div className="empty"><Mail/><b>No hay mensajes en esta categoría</b></div>}</div>
  {pages>1&&<div className="pager"><button disabled={mailPage<=1} onClick={()=>onPage(mailPage-1)}><ChevronLeft/>Anterior</button><span>Página {mailPage} de {pages}</span><button disabled={mailPage>=pages} onClick={()=>onPage(mailPage+1)}>Siguiente<ChevronRight/></button></div>}
 </>
}

function AdvancedSearch({value,onChange,onClose,onSearch}:{value:SearchFilters;onChange:(value:SearchFilters)=>void;onClose:()=>void;onSearch:()=>void}){const set=<K extends keyof SearchFilters>(key:K,next:SearchFilters[K])=>onChange({...value,[key]:next});return <section className="advancedSearch"><div className="advancedHead"><div><SlidersHorizontal/><b>Búsqueda avanzada</b></div><button onClick={onClose}><X/></button></div><div className="advancedGrid"><label>De<input value={value.from} onChange={e=>set('from',e.target.value)} placeholder="remitente@dominio.com"/></label><label>Para<input value={value.to} onChange={e=>set('to',e.target.value)} placeholder="destinatario@dominio.com"/></label><label>Asunto<input value={value.subject} onChange={e=>set('subject',e.target.value)}/></label><label>Contiene las palabras<input value={value.contains} onChange={e=>set('contains',e.target.value)}/></label><label>No contiene<input value={value.exclude} onChange={e=>set('exclude',e.target.value)}/></label><label>Estado<select value={value.status} onChange={e=>set('status',e.target.value as SearchFilters['status'])}><option value="all">Todos</option><option value="unread">No leídos</option><option value="read">Leídos</option><option value="flagged">Destacados</option></select></label><label>Fecha desde<input type="date" value={value.since} onChange={e=>set('since',e.target.value)}/></label><label>Fecha hasta<input type="date" value={value.before} onChange={e=>set('before',e.target.value)}/></label><label className="sizeFilter">Tamaño<select value={value.size_op} onChange={e=>set('size_op',e.target.value as SearchFilters['size_op'])}><option value="">Cualquiera</option><option value="larger">Mayor que</option><option value="smaller">Menor que</option></select><input type="number" min="0" step="0.1" value={value.size_value} onChange={e=>set('size_value',e.target.value)}/><select value={value.size_unit} onChange={e=>set('size_unit',e.target.value as SearchFilters['size_unit'])}><option>KB</option><option>MB</option></select></label><label className="checkField"><input type="checkbox" checked={value.has_attachment} onChange={e=>set('has_attachment',e.target.checked)}/>Contiene archivos adjuntos <small>(detección aproximada)</small></label></div><p className="advancedNote">La búsqueda se realiza en la carpeta actual. Buscar en el cuerpo puede tardar si Solr/FTS no está activo.</p><div className="advancedActions"><button onClick={()=>onChange(emptySearch)}>Limpiar</button><button className="primary" onClick={onSearch}><Search/>Buscar</button></div></section>}

function DraftList({csrf,onOpen}:{csrf:string;onOpen:(draft:Draft)=>void}){const[items,setItems]=useState<Draft[]>([]);const[busy,setBusy]=useState(true);const[error,setError]=useState('');const load=()=>api.drafts().then(result=>setItems(result.drafts.map(item=>({...item,receipt_requested:Boolean(item.receipt_requested)})))).catch(e=>setError(e.message)).finally(()=>setBusy(false));useEffect(()=>{void load()},[]);async function remove(event:React.MouseEvent,id:string){event.stopPropagation();if(!confirm('¿Eliminar este borrador?'))return;try{await api.deleteDraft(id,csrf);setItems(current=>current.filter(item=>item.id!==id))}catch(e){setError((e as Error).message)}}return <div className="page managerPage draftPage"><div className="pageTitle"><div><h1>Borradores</h1><p>{items.length} borrador{items.length===1?'':'es'} guardado{items.length===1?'':'s'}.</p></div></div>{error&&<div className="error">{error}</div>}<div className="managerList">{items.map(item=><div className="draftRow" role="button" tabIndex={0} key={item.id} onClick={()=>onOpen(item)} onKeyDown={event=>{if(event.key==='Enter')onOpen(item)}}><FileText/><span><b>{item.subject||'(Sin asunto)'}</b><small>{item.to||'Sin destinatario'} · {plain(item.body_html).slice(0,100)||'Sin contenido'}</small></span><time>{item.updated_at?shortDate(item.updated_at):''}</time><button className="draftDelete" title="Eliminar borrador" onClick={event=>void remove(event,item.id)}><Trash2/></button></div>)}{!busy&&!items.length&&<div className="empty"><FileText/><b>No hay borradores guardados</b></div>}</div></div>}

function FolderManager({csrf,items,onChange}:{csrf:string;items:Folder[];onChange:(items:Folder[])=>void}){const[name,setName]=useState('');const[busy,setBusy]=useState(false);const[error,setError]=useState('');async function create(){if(!name.trim())return;setBusy(true);setError('');try{const result=await api.createFolder(name.trim(),csrf);onChange(result.folders);setName('')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}async function rename(item:Folder){const next=prompt('Nuevo nombre de la carpeta',item.name);if(!next||next===item.name)return;setBusy(true);setError('');try{onChange((await api.renameFolder(item.name,next,csrf)).folders)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}async function remove(item:Folder){if(!confirm(`Se eliminará la carpeta “${item.name}”. Los mensajes que contiene pueden perderse. ¿Continuar?`))return;setBusy(true);setError('');try{onChange((await api.deleteFolder(item.name,csrf)).folders)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <div className="page managerPage"><div className="pageTitle"><div><h1>Administrar carpetas</h1><p>Las carpetas se crean directamente en IMAP y también aparecerán en Roundcube.</p></div></div>{error&&<div className="error">{error}</div>}<div className="managerCreate"><input value={name} maxLength={120} onChange={e=>setName(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')void create()}} placeholder="Nombre de la nueva carpeta"/><button disabled={busy||!name.trim()} onClick={()=>void create()}><Plus/>Crear carpeta</button></div><div className="managerList">{items.map(item=><div className="managerRow" key={item.name}><div><FolderCog/><span><b>{folderNames[item.special||'']||displayFolderName(item.name)}</b><small>{item.name}</small></span></div>{item.special?<span className="systemBadge">Sistema</span>:<div><button disabled={busy} onClick={()=>void rename(item)}>Renombrar</button><button className="dangerButton" disabled={busy} onClick={()=>void remove(item)}>Eliminar</button></div>}</div>)}</div></div>}

function LabelManager({csrf,items,onChange}:{csrf:string;items:Label[];onChange:(items:Label[])=>void}){const[name,setName]=useState('');const[color,setColor]=useState('#2563eb');const[busy,setBusy]=useState(false);const[error,setError]=useState('');async function create(){if(!name.trim())return;setBusy(true);setError('');try{const result=await api.createLabel(name.trim(),color,csrf);onChange(result.labels);setName('')}catch(e){setError((e as Error).message)}finally{setBusy(false)}}async function edit(item:Label){const next=prompt('Nombre de la etiqueta',item.name);if(!next)return;setBusy(true);setError('');try{onChange((await api.updateLabel(item.id,next,item.color,csrf)).labels)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}async function remove(item:Label){if(!confirm(`¿Eliminar la etiqueta “${item.name}”? Los mensajes no se eliminarán.`))return;setBusy(true);setError('');try{onChange((await api.deleteLabel(item.id,csrf)).labels)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <div className="page managerPage"><div className="pageTitle"><div><h1>Etiquetas</h1><p>Organizan mensajes mediante palabras clave IMAP. Roundcube puede no mostrarlas con el mismo diseño.</p></div></div>{error&&<div className="error">{error}</div>}<div className="managerCreate"><input value={name} maxLength={60} onChange={e=>setName(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')void create()}} placeholder="Nombre de la etiqueta"/><input className="colorPicker" type="color" value={color} onChange={e=>setColor(e.target.value)}/><button disabled={busy||!name.trim()} onClick={()=>void create()}><Plus/>Crear etiqueta</button></div><div className="managerList">{items.map(item=><div className="managerRow" key={item.id}><div><span className="labelDot" style={{backgroundColor:item.color}}/><span><b>{item.name}</b><small>{item.keyword}</small></span></div><div><input aria-label={`Color de ${item.name}`} className="colorPicker" type="color" value={item.color} onChange={e=>void api.updateLabel(item.id,item.name,e.target.value,csrf).then(result=>onChange(result.labels)).catch(error=>setError(error.message))}/><button disabled={busy} onClick={()=>void edit(item)}>Renombrar</button><button className="dangerButton" disabled={busy} onClick={()=>void remove(item)}>Eliminar</button></div></div>)}{!items.length&&<div className="empty"><Tags/><b>Todavía no creaste etiquetas</b></div>}</div></div>}
function Reader({data,folder,csrf,onBack,onDeleted,spamAction}:{data:LoadedMessage;folder:string;csrf:string;onBack:()=>void;onDeleted:()=>void;spamAction?:SpamAction}){
 const{message,attachments,safeHtml,hasRemoteImages,remoteUrl}=data;const[thread,setThread]=useState<LoadedMessage[]>([]);const[threadOpen,setThreadOpen]=useState(false);const[remote,setRemote]=useState(false);const[deleting,setDeleting]=useState(false);const[error,setError]=useState('');
 useEffect(()=>{let active=true;setThread([]);setThreadOpen(false);if(!message.thread_id)return;api.thread(folder,message.thread_id,message.uid).then(result=>{if(active)setThread(result.messages.sort((a,b)=>new Date(b.message.date).valueOf()-new Date(a.message.date).valueOf()))}).catch(()=>{});return()=>{active=false}},[folder,message.thread_id,message.uid]);
 async function remove(){if(!confirm('¿Mover este mensaje a la Papelera?'))return;setDeleting(true);setError('');try{await api.deleteMessage(folder,message.uid,csrf);onDeleted()}catch(e){setError((e as Error).message);setDeleting(false)}}
 async function block(){if(!confirm(`¿Bloquear a ${message.from} y mover este mensaje a Spam?`))return;setDeleting(true);setError('');try{await api.blockSender(folder,message.uid,csrf);onDeleted()}catch(e){setError((e as Error).message);setDeleting(false)}}
 if(spamAction?.label==='Spam')spamAction={label:'Bloquear remitente',onClick:()=>void block()};
 function draft(mode:'reply'|'replyAll'|'forward'){const replySubject=/^re:/i.test(message.subject)?message.subject:`Re: ${message.subject}`;const forwardSubject=/^fwd:/i.test(message.subject)?message.subject:`Fwd: ${message.subject}`;const quote=`<br><br><div style="border-left:2px solid #ccd2dc;padding-left:12px"><p>El ${escapeHtml(message.date)}, ${escapeHtml(message.from)} escribió:</p>${safeHtml||`<pre>${escapeHtml(message.text)}</pre>`}</div>`;const sender=emailFromHeader(message.from);const own=(sessionStorage.getItem('axerok-account')||'').toLowerCase();const copied=mode==='replyAll'?[...new Set(recipientEmails(`${message.to},${message.cc}`).filter(email=>email!==own&&email!==sender))].join(', '):'';window.dispatchEvent(new CustomEvent('axerok:compose',{detail:{...emptyDraft,to:mode==='forward'?'':sender,cc:copied,subject:mode==='forward'?forwardSubject:replySubject,body_html:quote}}))}
 return <article className="reader"><div className="readerbar"><button className="round" onClick={onBack} title="Volver"><ChevronLeft/></button><button className="readerAction" onClick={()=>setThreadOpen(true)}>Expandir hilo</button><button className="readerAction" onClick={()=>setThreadOpen(false)}>Contraer hilo</button><button className="readerAction" onClick={()=>draft('reply')}><Reply/>Responder</button><button className="readerAction" onClick={()=>draft('replyAll')}><ReplyAll/>Responder a todos</button><button className="readerAction" onClick={()=>draft('forward')}><Forward/>Reenviar</button><button className="round" onClick={remove} disabled={deleting} title="Mover a la Papelera"><Trash2/></button>{spamAction&&<button className="readerAction" onClick={spamAction.onClick}><Inbox/>{spamAction.label}</button>}</div>{error&&<div className="error banner">{error}</div>}<div className="message"><h1>{message.subject}{thread.length>0&&<small className="threadCount"> {thread.length+1}</small>}</h1><div className="sender"><div className="user">{message.from.slice(0,2).toUpperCase()}</div><div><b>{message.from}</b><small>para {message.to}</small></div><time>{shortDate(message.date)}</time></div>{hasRemoteImages&&!remote&&<div className="remoteNotice"><span>Las imágenes externas están bloqueadas para proteger tu privacidad.</span><button onClick={()=>setRemote(true)}>Mostrar imágenes</button></div>}{safeHtml?<iframe sandbox="allow-popups allow-popups-to-escape-sandbox" referrerPolicy="no-referrer" src={remote?remoteUrl:undefined} srcDoc={remote?undefined:safeHtml}/>:<p className="plain">{message.text}</p>}{attachments.length>0&&<div className="downloads">{attachments.map(item=><AttachmentPreview key={item.url} file={item}/>)}</div>}{thread.length>0&&<section className="threadHistory"><h2>Mensajes anteriores</h2>{thread.map(item=><details className="threadMessage" open={threadOpen} key={`${item.message.uid}-${item.message.date}`}><summary><b>{item.message.from}</b><span>{shortDate(item.message.date)}</span></summary><div>{item.safeHtml?<iframe sandbox="allow-popups allow-popups-to-escape-sandbox" referrerPolicy="no-referrer" srcDoc={item.safeHtml}/>:<p className="plain">{item.message.text}</p>}{item.attachments.length>0&&<div className="downloads">{item.attachments.map(file=><AttachmentPreview key={file.url} file={file}/>)}</div>}</div></details>)}</section>}</div></article>
}

function Composer({from,csrf,preferences,initialDraft,onClose:onComposerClose,onSent}:{from:string;csrf:string;preferences:Preferences;initialDraft:Draft|null;onClose:()=>void;onSent:(warning:string)=>void}){
 const freshDraft=()=>({...emptyDraft,id:crypto.randomUUID(),bcc:preferences.default_bcc,receipt_requested:preferences.receipt_default,body_html:preferences.signature_html?`<div><br></div><br><div>${preferences.signature_html}</div>`:''});const[draft,setDraft]=useState<Draft>(initialDraft?{...initialDraft,id:initialDraft.id||crypto.randomUUID()}:freshDraft());const[drafts,setDrafts]=useState<Draft[]>([]);const[templates,setTemplates]=useState<MailTemplate[]>([]);const[files,setFiles]=useState<File[]>([]);const[contacts,setContacts]=useState<Contact[]>([]);const[identities,setIdentities]=useState<Identity[]>([]);const[identityId,setIdentityId]=useState('');const[dragging,setDragging]=useState(false);const[busy,setBusy]=useState(false);const[closing,setClosing]=useState(false);const[pending,setPending]=useState(false);const[undoSeconds,setUndoSeconds]=useState(0);const[error,setError]=useState('');const[savedText,setSaved]=useState('');const editor=useRef<HTMLDivElement>(null);const picker=useRef<HTMLInputElement>(null);const saveQueue=useRef<Promise<unknown>>(Promise.resolve());const sendKey=useRef(crypto.randomUUID());const sendTimer=useRef<number|null>(null);
 useEffect(()=>{Promise.all([api.contacts(),api.recentRecipients()]).then(([contactsResult,recentResult])=>{const merged=[...contactsResult.contacts,...recentResult.contacts.filter(recent=>!contactsResult.contacts.some(contact=>contact.email.toLowerCase()===recent.email.toLowerCase()))];setContacts(merged)}).catch(()=>{});api.identities().then(result=>{setIdentities(result.identities);setIdentityId(result.identities[0]?.id||'')}).catch(()=>{})},[]);
 const activeTemplate=useRef('');
 useEffect(()=>{api.templates().then(result=>setTemplates(result.templates)).catch(()=>{})},[]);
 useEffect(()=>{if(initialDraft){const persisted=Boolean(initialDraft.id);const value={...initialDraft,id:initialDraft.id||crypto.randomUUID(),bcc:initialDraft.bcc||preferences.default_bcc,receipt_requested:persisted?Boolean(initialDraft.receipt_requested):preferences.receipt_default,body_html:persisted?initialDraft.body_html:`${initialDraft.body_html}${preferences.signature_html?`<br><div>${preferences.signature_html}</div>`:''}`};setDraft(value);if(editor.current)editor.current.innerHTML=value.body_html;return}api.drafts().then(result=>setDrafts(result.drafts.map(item=>({...item,receipt_requested:Boolean(item.receipt_requested)})))).catch(()=>{})},[]);
 useEffect(()=>{const timer=setTimeout(()=>{if(hasDraftContent(draft)||files.length){saveQueue.current=saveQueue.current.catch(()=>undefined).then(()=>api.saveDraft(draft,csrf,files)).then(result=>{setDrafts(items=>[result.draft,...items.filter(item=>item.id!==result.draft.id)]);if(files.length){setDraft(current=>({...current,attachments:result.draft.attachments||[]}));setFiles([])}setSaved('Guardado')}).catch(()=>setSaved('No guardado'))}},900);return()=>clearTimeout(timer)},[draft,csrf,files]);
 useEffect(()=>{if(!pending)return;const timer=window.setInterval(()=>setUndoSeconds(value=>Math.max(0,value-1)),1000);return()=>window.clearInterval(timer)},[pending]);
 useEffect(()=>()=>{if(sendTimer.current!==null)window.clearTimeout(sendTimer.current)},[]);
 function command(name:string,value?:string){editor.current?.focus();document.execCommand(name,false,value);setDraft(d=>({...d,body_html:editor.current?.innerHTML||''}))}
 function addFiles(input:FileList|null){if(!input)return;setFiles(current=>{const known=new Set(current.map(fileKey));return [...current,...Array.from(input).filter(file=>{const key=fileKey(file);if(known.has(key))return false;known.add(key);return true})].slice(0,10)})}
 async function deliver(){setPending(false);setBusy(true);setError('');try{const body=new FormData();body.set('csrf',csrf);body.set('idempotency_key',sendKey.current);body.set('identity_id',identityId);body.set('draft_attachment_ids',(draft.attachments||[]).map(item=>item.id).join(','));Object.entries(draft).forEach(([key,value])=>{if(key!=='attachments')body.set(key,value===true?'1':value===false?'0':String(value))});files.forEach(file=>body.append('attachments[]',file,file.name));const result=await api.send(body);onSent(result.warning)}catch(e){setError((e as Error).message);setBusy(false)}}
 function send(){if(busy||pending)return;setError('');if(!draft.to.trim()){setError('Ingresá al menos un destinatario.');return}if(!plain(draft.body_html)&&(draft.attachments?.length||0)===0&&files.length===0){setError('Escribí el contenido del mensaje o adjuntá un archivo.');return}setBusy(true);setPending(true);setUndoSeconds(5);setSaved('Envío pendiente');sendTimer.current=window.setTimeout(()=>{sendTimer.current=null;void deliver()},5000)}
 function undoSend(){if(sendTimer.current!==null)window.clearTimeout(sendTimer.current);sendTimer.current=null;setBusy(false);setPending(false);setUndoSeconds(0);setSaved('Envío cancelado')}
 function openDraft(id:string){const value=drafts.find(item=>item.id===id);if(!value)return;setDraft(value);setFiles([]);setSaved('');if(editor.current)editor.current.innerHTML=value.body_html}
 function newDraft(){const value=freshDraft();setDraft(value);setFiles([]);setSaved('');if(editor.current)editor.current.innerHTML=value.body_html}
 function openTemplate(id:string){const template=templates.find(item=>item.id===id);if(!template)return;activeTemplate.current=id;setDraft(value=>({...value,subject:template.subject,body_html:template.body_html}));if(editor.current)editor.current.innerHTML=template.body_html;setSaved(`Plantilla: ${template.name}`)}
 async function saveTemplate(){const name=prompt('Nombre de la plantilla');if(!name?.trim())return;try{const result=await api.saveTemplate({name:name.trim(),subject:draft.subject,body_html:draft.body_html},csrf);setTemplates(result.templates);setSaved('Plantilla guardada')}catch(e){setError((e as Error).message)}}
 async function deleteTemplate(){const id=activeTemplate.current;if(!id||!confirm('¿Eliminar la plantilla seleccionada?'))return;try{setTemplates((await api.deleteTemplate(id,csrf)).templates);activeTemplate.current='';setSaved('Plantilla eliminada')}catch(e){setError((e as Error).message)}}
 function onClose(){void closeDraft()}
 async function closeDraft(){if(closing)return;if(!hasDraftContent(draft)&&!files.length){onComposerClose();return}setClosing(true);setSaved('Guardando…');setError('');try{saveQueue.current=saveQueue.current.catch(()=>undefined).then(()=>api.saveDraft(draft,csrf,files));await saveQueue.current;onComposerClose()}catch(e){setError((e as Error).message);setSaved('No guardado');setClosing(false)}}
 async function discard(){setError('');try{await api.deleteDraft(draft.id,csrf);onComposerClose()}catch(e){setError((e as Error).message);setSaved('No se pudo descartar')}}
 const saved=<span className="draftControls">{pending?<button type="button" className="undoSend" onClick={undoSend}><Undo2/>Deshacer envío ({undoSeconds})</button>:<><select aria-label="Abrir borrador" value={drafts.some(item=>item.id===draft.id)?draft.id:''} onChange={event=>openDraft(event.target.value)}><option value="">{drafts.length?`${drafts.length} borradores`:'Sin borradores'}</option>{drafts.map(item=><option value={item.id} key={item.id}>{item.subject||item.to||'Sin asunto'}</option>)}</select><select aria-label="Insertar plantilla" defaultValue="" onChange={event=>{openTemplate(event.target.value);event.currentTarget.value=''}}><option value="">Plantillas</option>{templates.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select><button type="button" title="Guardar como plantilla" onClick={()=>void saveTemplate()}><Save/></button><button type="button" title="Eliminar plantilla seleccionada" onClick={()=>void deleteTemplate()}><Trash2/></button><button type="button" onClick={newDraft}><Plus/>Nuevo</button></>}<i>{savedText}</i></span>;
 return <div className={`composer ${dragging?'dragging':''}`} onDragEnter={e=>{e.preventDefault();setDragging(true)}} onDragOver={e=>e.preventDefault()} onDragLeave={e=>{if(e.currentTarget===e.target)setDragging(false)}} onDrop={e=>{e.preventDefault();setDragging(false);addFiles(e.dataTransfer.files)}}><div className="composeHead"><b>Mensaje nuevo</b><div><span>{saved}</span><button onClick={onClose}><X/></button></div></div><div className="field"><span>De</span><b>{preferences.display_name?`${preferences.display_name} <${from}>`:from}</b>{identities.length>0&&<select aria-label="Identidad de envío" value={identityId} onChange={e=>{const next=identities.find(item=>item.id===e.target.value);setIdentityId(e.target.value);if(next?.signature_html&&editor.current){editor.current.innerHTML="<div><br></div><br><div>"+next.signature_html+"</div>";setDraft(current=>({...current,body_html:editor.current?.innerHTML||current.body_html}))}}}><option value="">Cuenta principal</option>{identities.map(identity=><option key={identity.id} value={identity.id}>{identity.display_name?identity.display_name+" <"+identity.email+">":identity.email}</option>)}</select>}</div><div className="field"><span>Para</span><RecipientInput value={draft.to} onChange={to=>setDraft({...draft,to})} contacts={contacts} placeholder="Destinatarios"/></div><div className="field compact"><span>Cc</span><RecipientInput value={draft.cc} onChange={cc=>setDraft({...draft,cc})} contacts={contacts} placeholder=""/><span>Cco</span><RecipientInput value={draft.bcc} onChange={bcc=>setDraft({...draft,bcc})} contacts={contacts} placeholder=""/></div><div className="field"><span>Asunto</span><input value={draft.subject} onChange={e=>setDraft({...draft,subject:e.target.value})}/><select aria-label="Prioridad" value={draft.priority} onChange={e=>setDraft({...draft,priority:e.target.value as Draft['priority']})}><option value="low">Prioridad baja</option><option value="normal">Prioridad normal</option><option value="high">Prioridad alta</option></select></div><div ref={editor} className="editor" contentEditable data-placeholder="Escribí tu mensaje…" onInput={e=>setDraft({...draft,body_html:e.currentTarget.innerHTML})}/><div className="formatbar"><Tool icon={<Undo2/>} action={()=>command('undo')}/><Tool icon={<Redo2/>} action={()=>command('redo')}/><Tool icon={<Bold/>} action={()=>command('bold')}/><Tool icon={<Italic/>} action={()=>command('italic')}/><Tool icon={<Underline/>} action={()=>command('underline')}/><Tool icon={<List/>} action={()=>command('insertUnorderedList')}/><Tool icon={<ListOrdered/>} action={()=>command('insertOrderedList')}/><Tool icon={<Link/>} action={()=>{const url=prompt('URL del enlace');if(url)command('createLink',url)}}/></div>{dragging&&<div className="dropNotice"><Paperclip/>Soltá los archivos para adjuntarlos</div>}{((draft.attachments?.length||0)>0||files.length>0)&&<div className="fileChips">{(draft.attachments||[]).map(item=><span key={item.id}>{item.name}<button onClick={()=>setDraft(current=>({...current,attachments:(current.attachments||[]).filter(file=>file.id!==item.id)}))}><X/></button></span>)}{files.map((file,index)=><span key={fileKey(file)}>{file.name}<button onClick={()=>setFiles(files.filter((_,i)=>i!==index))}><X/></button></span>)}</div>}<label className="receipt"><input type="checkbox" checked={draft.receipt_requested} onChange={e=>setDraft({...draft,receipt_requested:e.target.checked})}/> Solicitar confirmación de lectura <small>(se envía la solicitud, pero el destinatario puede rechazarla)</small></label>{error&&<div className="error composeError">{error}</div>}<div className="composeActions"><button className="primary" disabled={busy} onClick={send}><Send/>{busy?'Enviando…':'Enviar'}</button><button title="Adjuntar" onClick={()=>picker.current?.click()}><Paperclip/></button><input ref={picker} type="file" multiple hidden onChange={e=>addFiles(e.target.files)}/><button title="Descartar" onClick={discard}><Trash2/></button></div></div>
}
function Tool({icon,action}:{icon:React.ReactNode;action:()=>void}){return <button type="button" onMouseDown={e=>e.preventDefault()} onClick={action}>{icon}</button>}
function Contacts({csrf}:{csrf:string}){const[items,setItems]=useState<Contact[]>([]);const[readOnly,setReadOnly]=useState(false);const[error,setError]=useState('');const[notice,setNotice]=useState('');const[busy,setBusy]=useState(false);const picker=useRef<HTMLInputElement>(null);const load=()=>api.contacts().then(r=>{setItems(r.contacts);setReadOnly(Boolean(r.read_only))}).catch(e=>setError(e.message));useEffect(()=>{void load()},[]);async function importFile(file?:File){if(!file)return;setBusy(true);setError('');setNotice('');try{const result=await api.importContacts(file,csrf);setNotice(`${result.stats.created} creados, ${result.stats.updated} actualizados${result.stats.invalid?`, ${result.stats.invalid} omitidos`:''}.`);await load()}catch(e){setError((e as Error).message)}finally{setBusy(false);if(picker.current)picker.current.value=''}}async function exportFile(){setBusy(true);setError('');try{const result=await api.exportContacts();const url=URL.createObjectURL(new Blob([result.contents],{type:'text/vcard;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=result.filename;link.click();URL.revokeObjectURL(url)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <div className="page"><div className="pageTitle"><div><h1>Contactos</h1><p>{readOnly?'Lectura directa desde Roundcube. Editá contactos desde Roundcube.':`${items.length} contactos sincronizados con AxerOK Mail.`}</p></div><div className="contactActions"><button disabled={busy||readOnly} onClick={()=>picker.current?.click()}><Upload/>Importar vCard</button><input ref={picker} hidden type="file" accept=".vcf,text/vcard,text/x-vcard" onChange={e=>void importFile(e.target.files?.[0])}/><button disabled={busy||!items.length} onClick={()=>void exportFile()}><Download/>Exportar</button></div></div>{error&&<div className="error">{error}</div>}{notice&&<div className="success">{notice}</div>}{!readOnly&&<RoundcubeImport csrf={csrf} onImported={()=>void load()} />}<div className="contactTable"><b>Nombre</b><b>Email</b><b>Teléfono</b><b>Organización</b>{items.map(item=><Fragment key={item.id}><span>{item.name||'Sin nombre'}</span><a href={`mailto:${item.email}`}>{item.email}</a><span>{item.phone}</span><span>{item.organization}</span></Fragment>)}</div></div>}
function PreferencesView({csrf,value,onChange,onNotice}:{csrf:string;value:Preferences;onChange:(p:Preferences)=>void;onNotice:(s:string)=>void}){const[busy,setBusy]=useState(false);const ref=useRef<HTMLDivElement>(null);useEffect(()=>{if(ref.current)ref.current.innerHTML=value.signature_html},[value.signature_html]);function command(name:string,next?:string){ref.current?.focus();document.execCommand(name,false,next)}async function save(){setBusy(true);const next={...value,signature_html:ref.current?.innerHTML||''};try{await api.savePreferences(next,csrf);onChange(next);onNotice('Preferencias guardadas.')}finally{setBusy(false)}}const field=(key:'display_name'|'organization'|'reply_to'|'default_bcc',label:string,type='text')=><label>{label}<input type={type} value={value[key]} onChange={e=>onChange({...value,[key]:e.target.value})}/></label>;return <div className="page settingsPage"><h1>Configuración</h1><h2>Identidad y datos personales</h2><div className="identityGrid">{field('display_name','Nombre para mostrar')}{field('organization','Empresa u organización')}{field('reply_to','Responder a','email')}{field('default_bcc','Cco predeterminado')}</div><p>Estos datos se incorporan a los encabezados de los mensajes enviados.</p><h2>Vista de bandeja</h2><div className="viewOptions"><label>Densidad<select value={value.view_density} onChange={e=>onChange({...value,view_density:e.target.value as Preferences['view_density']})}><option value="default">Predeterminada</option><option value="comfortable">Cómoda</option><option value="compact">Compacta</option></select></label><label>Tipo de bandeja<select value={value.inbox_view} onChange={e=>onChange({...value,inbox_view:e.target.value as Preferences['inbox_view']})}><option value="categories">Categorías</option><option value="default">Predeterminada</option><option value="unread">No leídos primero</option><option value="starred">Destacados primero</option></select></label></div><p>“Contactos” muestra remitentes presentes en tu libreta y clasifica solamente la página cargada; no es una carpeta IMAP.</p><h2>Firma</h2><p>Se agregará automáticamente a los mensajes nuevos.</p><div className="formatbar signatureTools"><Tool icon={<Bold/>} action={()=>command('bold')}/><Tool icon={<Italic/>} action={()=>command('italic')}/><Tool icon={<Underline/>} action={()=>command('underline')}/><Tool icon={<List/>} action={()=>command('insertUnorderedList')}/><Tool icon={<Link/>} action={()=>{const url=prompt('URL del enlace');if(url)command('createLink',url)}}/></div><div ref={ref} className="signatureEditor" contentEditable data-placeholder="Escribí tu firma…"/><label className="receipt"><input type="checkbox" checked={value.receipt_default} onChange={e=>onChange({...value,receipt_default:e.target.checked})}/> Solicitar confirmación de lectura por defecto <small>(no garantiza respuesta)</small></label><button className="saveButton" disabled={busy} onClick={save}><Save/>{busy?'Guardando…':'Guardar cambios'}</button></div>}
function RoundcubeImport({csrf,onImported}:{csrf:string;onImported:()=>void}){const[status,setStatus]=useState<{personal:number;collected:number;carddav:number;identity:boolean}|null>(null);const[reason,setReason]=useState('');const[collected,setCollected]=useState(false);const[identity,setIdentity]=useState(false);const[busy,setBusy]=useState(false);const[notice,setNotice]=useState('');useEffect(()=>{api.roundcubeStatus().then(result=>{if(result.available&&result.status)setStatus(result.status);else setReason(result.reason||'Roundcube no está disponible.')}).catch(error=>setReason(error.message))},[]);async function run(){setBusy(true);setNotice('');try{const result=await api.importRoundcube(collected,identity,csrf);setNotice(`${result.stats.created} creados, ${result.stats.updated} actualizados${result.identity_imported?', identidad importada':''}.`);onImported()}catch(error){setReason((error as Error).message)}finally{setBusy(false)}}return <section className="roundcubeImport"><h2>Importar desde Roundcube</h2>{status?<><p>Encontrados: {status.personal} personales, {status.collected} recopilados y {status.carddav} CardDAV.</p><label><input type="checkbox" checked readOnly/> Contactos personales</label><label><input type="checkbox" checked={collected} onChange={e=>setCollected(e.target.checked)}/> Incluir destinatarios recopilados ({status.collected})</label><label><input type="checkbox" checked={identity} disabled={!status.identity} onChange={e=>setIdentity(e.target.checked)}/> Importar nombre, empresa, firma y datos de identidad</label><button disabled={busy} onClick={()=>void run()}>{busy?'Importando…':'Importar ahora'}</button></>:<p className="roundcubeUnavailable">{reason||'Buscando una base compatible…'}</p>}{notice&&<div className="success">{notice}</div>}</section>}

function Brand(){return <div className="brand"><img className="brandLight" src="icon.png" alt="AxerOK Mail"/><img className="brandDark" src="icon2.png" alt="AxerOK Mail"/></div>}
function folderIcon(special:string|null){if(special==='sent')return <Send/>;if(special==='trash')return <Trash2/>;if(special==='archive')return <Archive/>;if(special==='drafts')return <FileText/>;return <Inbox/>}
function shortDate(value:string){const date=new Date(value);return Number.isNaN(date.valueOf())?value:new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(date)}
function plain(html:string){const element=document.createElement('div');element.innerHTML=html;return element.textContent?.trim()||''}
function hasDraftContent(draft:Draft){return Boolean(draft.to||draft.cc||draft.bcc||draft.subject||plain(draft.body_html))}
function escapeHtml(value:string){return value.replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]||char))}
function fileKey(file:File){return `${file.name}-${file.size}-${file.lastModified}`}
function emailFromHeader(value:string){const match=value.match(/<([^<>]+)>/);return (match?.[1]||value).trim().toLowerCase()}
function recipientEmails(value:string){return value.split(/[;,]/).map(emailFromHeader).filter(value=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value))}
function formatBytes(bytes:number){if(bytes<1024)return `${bytes} B`;if(bytes<1048576)return `${(bytes/1024).toFixed(1)} KB`;return `${(bytes/1048576).toFixed(1)} MB`}
